import type { ParsedTransaction } from '../../src/types/parsers'

export function parseKlar(text: string): ParsedTransaction[] {
  const transactions: ParsedTransaction[] = []
  
  // 1. Extraer el año del periodo (Ej: "01 de enero - 31 de enero, 2026")
  let year = new Date().getFullYear().toString()
  const yearMatch = /(?:enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre).*?(\d{4})/i.exec(text)
  if (yearMatch) {
    year = yearMatch[1]
  }

  // 2. Extraer transacciones (Ej: "08/01 Pago línea de crédito $1.46 $0.00")
  // El regex captura: Fecha (DD/MM), Concepto, Cargo ($X.XX), Abono ($X.XX)
  const regex = /(\d{2}\/\d{2})\s+(.+?)\s+\$([\d,]+\.\d{2})\s+\$([\d,]+\.\d{2})/g
  let match

  while ((match = regex.exec(text)) !== null) {
    const [_, dateStr, descriptionRaw, cargosStr, abonosStr] = match
    
    // Parse Date
    const [day, month] = dateStr.split('/')
    const date = `${year}-${month}-${day}`
    
    // Parse Amounts
    const cargo = parseFloat(cargosStr.replace(/,/g, ''))
    const abono = parseFloat(abonosStr.replace(/,/g, ''))
    
    const description = descriptionRaw.trim()

    // Skip if both are 0
    if (cargo === 0 && abono === 0) continue

    // Si tiene un cargo, registramos el gasto
    if (cargo > 0) {
      transactions.push({
        date,
        description,
        amount: cargo,
        type: 'gasto'
      })
    }
    
    // Si tiene un abono, registramos el ingreso
    // NOTA: Si una misma línea tiene cargo y abono (ej. traspaso interno), se registrarán ambos para cuadrar
    if (abono > 0) {
      // Diferenciar descripciones si es una transacción doble para mayor claridad
      const descPostfix = (cargo > 0 && abono > 0) ? ' (Abono)' : ''
      transactions.push({
        date,
        description: `${description}${descPostfix}`,
        amount: abono,
        type: 'ingreso'
      })
    }
  }

  // Ordenar cronológicamente (opcional, el parser a veces lee desordenado dependiendo del OCR)
  return transactions.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
}
